import type { ConfigType } from '@plone/registry';

/**
 * Applies the server configuration (`config/server`) of the app's add-ons, in
 * add-on order, to the registry configuration. Generated by the Plone
 * registry Vite plugin. Only server code imports it.
 */
export default function applyServerAddonConfiguration(
  config: ConfigType,
): ConfigType;
